import React, { useState, useEffect } from "react";
import { X } from "lucide-react";

function JobForm({ job, onClose, onSubmit }) {
  const [formData, setFormData] = useState({
    title: "",
    role: "",
    skillset: "",
    ctc: "",
    location: "",
    experience: "",
    jobType: "Full-time",
    department: "",
    description: "",
    responsibilities: "",
    qualifications: "",
    benefits: "",
    deadline: "",
  });

  useEffect(() => { if (job) setFormData(job); }, [job]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = () => {
    // Fill empty fields with "NA"
    const filledData = {};
    Object.keys(formData).forEach((key) => {
      filledData[key] = formData[key] ? formData[key] : "NA";
    });

    // Check mandatory fields
    const mandatoryFields = ["title","role","skillset","ctc","location","experience","description"];
    for (let field of mandatoryFields) {
      if (!formData[field]) {
        alert(`${field.charAt(0).toUpperCase() + field.slice(1)} is mandatory!`);
        return;
      }
    }

    onSubmit(filledData);
  };

  const resetForm = () => {
    setFormData({
      title: "", role: "", skillset: "", ctc: "", location: "", experience: "", jobType: "Full-time",
      department: "", description: "", responsibilities: "", qualifications: "", benefits: "", deadline: ""
    });
    onClose();
  };

  const styles = {
    overlay: { position: "fixed", top:0, left:0, right:0, bottom:0, backgroundColor: "rgba(0,0,0,0.6)", display:"flex", alignItems:"flex-start", justifyContent:"center", paddingTop:"60px", zIndex:1000 },
    modal: { background:"#fff", width:"90%", maxWidth:"800px", borderRadius:"12px", boxShadow:"0 8px 30px rgba(0,0,0,0.2)", overflow:"hidden", animation:"fadeIn 0.3s ease" },
    header: { display:"flex", justifyContent:"space-between", alignItems:"center", padding:"18px 24px", borderBottom:"1px solid #e2e8f0" },
    title: { fontSize:"20px", color:"#1e293b" },
    content: { padding:"24px", maxHeight:"70vh", overflowY:"auto" },
    label: { fontSize:"14px", fontWeight:500, color:"#374151", marginBottom:"6px", display:"block" },
    mandatory: { color:"red", marginLeft:"3px" },
    input: { width:"100%", padding:"10px 12px", marginBottom:"18px", border:"1px solid #cbd5e1", borderRadius:"8px", fontSize:"14px", color:"#1e293b", outline:"none" },
    footer: { display:"flex", justifyContent:"flex-end", gap:"12px", padding:"16px 24px", borderTop:"1px solid #e2e8f0", backgroundColor:"#f9fafb" },
    btn: { padding:"10px 16px", border:"none", borderRadius:"8px", fontSize:"14px", cursor:"pointer" },
    save: { background:"#2563eb", color:"#fff" },
    cancel: { background:"#e2e8f0", color:"#1e293b" }
  };

  // Example placeholders for inputs
  const placeholders = {
    title: "e.g. Frontend Developer",
    role: "e.g. UI Engineer",
    skillset: "e.g. React, JS, CSS",
    ctc: "e.g. 3 LPA, 5 LPA",
    location: "e.g. Bengaluru, Remote",
    experience: "e.g. 2 years, 5 years",
    department: "e.g. Engineering, HR",
    description: "Job description here...",
    responsibilities: "Key responsibilities...",
    qualifications: "Required qualifications...",
    benefits: "e.g. Health insurance, Paid leaves",
    deadline: ""
  };

  const mandatoryFields = ["title","role","skillset","ctc","location","experience","description"];

  return (
    <div style={styles.overlay}>
      <div style={styles.modal}>
        <div style={styles.header}>
          <h2 style={styles.title}>{job ? "Edit Job" : "Add New Job"}</h2>
          <button onClick={resetForm}><X size={22} /></button>
        </div>
        <div style={styles.content}>
          {Object.keys(formData).map((field) => (
            <div key={field} style={{ marginBottom:"12px" }}>
              <label style={styles.label}>
                {field.charAt(0).toUpperCase() + field.slice(1)}
                {mandatoryFields.includes(field) && <span style={styles.mandatory}>*</span>}
              </label>
              {field === "jobType" ? (
                <select name={field} value={formData[field]} onChange={handleChange} style={styles.input}>
                  <option>Full-time</option>
                  <option>Part-time</option>
                  <option>Contract</option>
                  <option>Internship</option>
                </select>
              ) : field === "description" || field === "responsibilities" || field === "qualifications" || field === "benefits" ? (
                <textarea name={field} rows={field==="description"?4:3} value={formData[field]} onChange={handleChange} placeholder={placeholders[field]} style={styles.input}></textarea>
              ) : (
                <input type={field==="deadline"?"date":"text"} name={field} value={formData[field]} onChange={handleChange} placeholder={placeholders[field]} style={styles.input} />
              )}
            </div>
          ))}
        </div>
        <div style={styles.footer}>
          <button onClick={handleSubmit} style={{ ...styles.btn, ...styles.save }}>{job ? "Update Job" : "Add Job"}</button>
          <button onClick={resetForm} style={{ ...styles.btn, ...styles.cancel }}>Cancel</button>
        </div>
      </div>
    </div>
  );
}

export default JobForm;
